def transform(g):
    g=[r[:] for r in g]; h,w=len(g),len(g[0])
    br=None
    for r in range(h):
        nz=[c for c in range(w) if g[r][c]]
        if len(nz)>=2: br=r; bar=nz; break
    colmap={c:g[br][c] for c in bar}
    markers={}
    for r in range(h):
        for c in range(w):
            v=g[r][c]
            if v and not (r==br and c in colmap) and v in colmap.values():
                markers[v]=(r,c)
    out=[r[:] for r in g]
    for sc,v in colmap.items():
        end = markers[v][0] if v in markers else h-1
        for rr in range(br+1,end+1): out[rr][sc]=v
    for v,(r,c) in markers.items():
        sc=[cc for cc,col in colmap.items() if col==v][0]
        for cc in range(min(c,sc),max(c,sc)+1): out[r][cc]=v
    return out
out=transform(d4["input"])
print(out==d4["output"])
